import { get, handleApiError, post } from '@helpers/httpClient';

import {
  mapHikingRadishStatToFront,
  mapHikingRadishToFront,
  mapHikingRadishWithHikingToFront,
} from '../@mappers/hikingRadish.mapper';
import {
  IHikingRadishDTO,
  IHikingRadishDTOWithHiking,
  IHikingRadishStatDTO,
} from '../@types/DTO/hikingRadish.dto.types';

export const iAmHikingRadish = (data: { comment: string; id_hiking: number }) => {
  return post('/ajax/hiking/radish_harakiri.php', data).then<{ id: number }>(handleApiError);
};

export const addHikingRadish = (data: { id_hiking: number; id_user: number }) => {
  return post('/ajax/hiking/radish_add.php', data).then<{ id: number }>(handleApiError);
};

export const deleteHikingRadish = (data: { id_hiking: number; id: number }) => {
  return post('/ajax/hiking/radish_remove.php', data).then<{ success: boolean }>(handleApiError);
};

export interface IUncompletedUserRadish {
  id: string;
  id_hiking: string;
  comment: string;
  date: string;
  killer: string;
  name: string;
}
export const getUncompletedUserRadish = () => {
  return get('/ajax/users/is_radish.php').then<IUncompletedUserRadish[]>(handleApiError);
};

export const uncompletedRadishUpdate = (id: number, comment: string) => {
  return post('/ajax/hiking/radish_comment.php', { id, comment }).then(handleApiError);
};

export const getHikingRadish = async (id_hiking: number) => {
  const res = await get('/ajax/hiking/radish_by_hiking.php', { id_hiking }).then<
    IHikingRadishDTO[]
  >(handleApiError);
  return res.map(mapHikingRadishToFront);
};

export const getRadishStat = async () => {
  const res = await get('/ajax/hiking/radish_stat.php').then<{
    users: IHikingRadishStatDTO[];
    comments: string[];
    hikingCounts: Record<number, number>;
  }>(handleApiError);
  return {
    comments: res.comments,
    users: res.users.map(mapHikingRadishStatToFront),
    hikingCounts: res.hikingCounts,
  };
};

export const getRadishList = async (id_user?: number) => {
  const res = await get('/ajax/hiking/radish_all.php', { id_user }).then<
    IHikingRadishDTOWithHiking[]
  >(handleApiError);
  return res.map(mapHikingRadishWithHikingToFront);
};
