import {
  IHikingRadishDTO,
  IHikingRadishDTOWithHiking,
  IHikingRadishStatDTO,
} from '../@types/DTO/hikingRadish.dto.types';
import {
  IHikingRadish,
  IHikingRadishStat,
  IHikingRadishWithHiking,
} from '../@types/hikingRadish.types';

export const mapHikingRadishToFront = (backData: IHikingRadishDTO): IHikingRadish => {
  return {
    id: +backData.id,
    date: new Date(backData.date),
    comment: backData.comment,
    user: {
      id: +backData.user_id,
      name: backData.user_name,
      surname: backData.user_surname,
      photo: backData.user_photo,
    },
    isHarakiri: backData.harakiri == '1',
  };
};

export const mapHikingRadishWithHikingToFront = (
  backData: IHikingRadishDTOWithHiking,
): IHikingRadishWithHiking => {
  return {
    ...mapHikingRadishToFront(backData),
    hiking: {
      id: +backData.hiking_id,

      name: backData.hiking_name,
      ava: backData.hiking_ava,
      start: new Date(backData.hiking_start),
      finish: new Date(backData.hiking_finish),
    },
  };
};

export const mapHikingRadishStatToFront = (backData: IHikingRadishStatDTO): IHikingRadishStat => {
  return {
    count: +backData.cou,
    lastDate: new Date(backData.max_date),
    user: {
      id: +backData.user_id,
      name: backData.user_name,
      surname: backData.user_surname,
      photo: backData.user_photo,
    },
  };
};
